fn reverse(a: Vec<char>) -> Vec<char> {
    let n = a.len();
    if n == 0 {
        return Vec::new();
    }

    let mut b = vec!['\0'; n];
    for i in 0..n {
        b[i] = a[n - i - 1];
    }
    b
}

